<?php use App\Core\View; require BASE_PATH . '/app/Views/layouts/header.php'; ?>
<main id="conteudo" class="page-shell"><div class="page-heading"><p class="eyebrow">DWD Street</p><h1>Catálogo</h1></div><nav class="filters" aria-label="Categorias"><a class="<?= !$selectedCategory ? 'active' : '' ?>" href="index.php?rota=catalogo">Todos</a><?php foreach ($categories as $category): ?><a class="<?= $selectedCategory === (int) $category['id'] ? 'active' : '' ?>" href="index.php?rota=catalogo&amp;categoria=<?= (int) $category['id'] ?>"><?= View::escape($category['nome']) ?></a><?php endforeach; ?></nav><?php if (!$products): ?><p class="empty-state">Nenhum produto encontrado.</p><?php else: ?><div class="product-grid"><?php foreach ($products as $product): ?><?php $image = $product['imagem'] ?: 'assets/css/img/produto1.png'; $price = $product['preco_promocional'] ?: $product['preco']; ?><article class="product-card"><img src="<?= View::escape($image) ?>" alt="<?= View::escape($product['nome']) ?>" loading="lazy"><div class="product-card__body"><h2><?= View::escape($product['nome']) ?></h2><p>R$ <?= number_format((float) $price, 2, ',', '.') ?></p><?php if ((int) $product['estoque']): ?><form method="post" action="index.php?rota=carrinho/adicionar"><input type="hidden" name="produto_id" value="<?= (int) $product['id'] ?>"><button class="button button-dark">Adicionar</button></form><?php else: ?><span class="sold-out">Esgotado</span><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></main>
<?php require BASE_PATH . '/app/Views/layouts/footer.php'; ?>
